<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Desktop Environment</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Ubuntu', 'Segoe UI', -apple-system, sans-serif;
            background: #2b2b2b;
            color: #ffffff;
        }

        #desktop {
            width: 100vw;
            height: 100vh;
            background: linear-gradient(135deg, #1a1a1a 0%, #2d2d2d 100%);
            display: flex;
            flex-direction: column;
            position: relative;
            overflow: hidden;
        }

        .top-bar {
            height: 38px;
            background: rgba(0, 0, 0, 0.7);
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
            display: flex;
            align-items: center;
            padding: 0 20px;
            font-size: 14px;
            font-weight: 500;
        }

        .desktop-content {
            flex: 1;
            position: relative;
            overflow: hidden;
        }

        #taskbar {
            height: 60px;
            background: rgba(0, 0, 0, 0.6);
            border-top: 1px solid rgba(255, 255, 255, 0.1);
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 0 15px;
        }

        .taskbar-btn {
            padding: 8px 16px;
            min-width: 90px;
            height: 48px;
            background: linear-gradient(135deg, #3a3a3a, #2a2a2a);
            border: 1px solid rgba(255, 255, 255, 0.2);
            border-radius: 6px;
            cursor: pointer;
            color: #ffffff;
            font-size: 12px;
            font-weight: 500;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            transition: all 0.2s ease;
        }

        .taskbar-btn:hover {
            background: linear-gradient(135deg, #4a4a4a, #3a3a3a);
            border-color: rgba(255, 255, 255, 0.4);
            transform: translateY(-2px);
        }

        .taskbar-btn:active {
            transform: translateY(0);
        }

        .window {
            position: absolute;
            background: rgba(45, 45, 45, 0.95);
            border: 1px solid rgba(255, 255, 255, 0.12);
            border-radius: 8px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
            display: none;
            flex-direction: column;
            min-width: 360px;
            min-height: 240px;
            z-index: 100;
            backdrop-filter: blur(5px);
        }

        .window.active {
            display: flex;
        }

        .window-header {
            height: 40px;
            background: linear-gradient(90deg, rgba(60, 60, 60, 0.9), rgba(50, 50, 50, 0.9));
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 15px;
            cursor: grab;
            user-select: none;
            border-radius: 8px 8px 0 0;
        }

        .window-header:active {
            cursor: grabbing;
        }

        .window-title {
            font-size: 13px;
            font-weight: 600;
            color: #ffffff;
        }

        .window-controls {
            display: flex;
            gap: 6px;
        }

        .win-close {
            width: 32px;
            height: 32px;
            background: rgba(255, 59, 48, 0.15);
            border: 1px solid rgba(255, 59, 48, 0.25);
            border-radius: 4px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #ff6b6b;
            font-size: 18px;
            transition: all 0.2s ease;
            font-weight: 600;
        }

        .win-close:hover {
            background: rgba(255, 59, 48, 0.25);
            border-color: rgba(255, 59, 48, 0.4);
        }

        .window-content {
            flex: 1;
            overflow: auto;
            display: flex;
            flex-direction: column;
        }

        #files-path {
            background: rgba(0, 0, 0, 0.25);
            padding: 10px 15px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.08);
            font-size: 12px;
            font-family: 'Courier New', monospace;
            color: #e8e8e8;
            user-select: text;
        }

        .files-nav {
            display: flex;
            gap: 8px;
            padding: 8px 15px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.08);
        }

        .file-nav-btn {
            padding: 6px 12px;
            background: rgba(60, 60, 60, 0.6);
            border: 1px solid rgba(255, 255, 255, 0.15);
            border-radius: 4px;
            cursor: pointer;
            color: #e8e8e8;
            font-size: 11px;
            font-weight: 500;
            transition: all 0.2s ease;
        }

        .file-nav-btn:hover {
            background: rgba(70, 70, 70, 0.8);
            border-color: rgba(255, 255, 255, 0.3);
        }

        .file-list {
            flex: 1;
            overflow-y: auto;
            background: rgba(0, 0, 0, 0.15);
            padding: 0;
        }

        .fs-item {
            padding: 10px 15px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.04);
            cursor: pointer;
            user-select: none;
            display: flex;
            align-items: center;
            gap: 10px;
            font-size: 13px;
            transition: background 0.1s ease;
        }

        .fs-item:hover {
            background: rgba(255, 255, 255, 0.08);
        }

        .fs-item-icon {
            font-size: 16px;
            width: 20px;
            flex-shrink: 0;
        }

        .notepad-header {
            display: flex;
            flex-direction: column;
            gap: 0;
        }

        .notepad-tabs-area {
            display: flex;
            align-items: center;
            gap: 4px;
            background: rgba(0, 0, 0, 0.15);
            padding: 6px 8px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.08);
            overflow-x: auto;
            min-height: 36px;
        }

        #tabs {
            display: flex;
            gap: 4px;
            align-items: center;
            flex: 1;
            min-width: 0;
        }

        .tab {
            padding: 6px 12px;
            background: rgba(60, 60, 60, 0.5);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 4px;
            cursor: pointer;
            font-size: 11px;
            color: #a0a0a0;
            transition: all 0.15s ease;
            white-space: nowrap;
            flex-shrink: 0;
        }

        .tab:hover {
            background: rgba(70, 70, 70, 0.7);
            color: #e8e8e8;
        }

        .tab.active {
            background: rgba(70, 70, 70, 0.9);
            color: #ffffff;
            border-color: rgba(255, 255, 255, 0.25);
        }

        #new-tab {
            padding: 6px 10px;
            background: rgba(60, 60, 60, 0.5);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 4px;
            cursor: pointer;
            color: #a0a0a0;
            font-size: 14px;
            font-weight: 600;
            transition: all 0.15s ease;
            flex-shrink: 0;
            height: 24px;
            width: 24px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        #new-tab:hover {
            background: rgba(70, 70, 70, 0.7);
            color: #e8e8e8;
        }

        #editor {
            flex: 1;
            background: rgba(0, 0, 0, 0.2);
            border: none;
            padding: 15px;
            color: #e8e8e8;
            font-family: 'Courier New', monospace;
            font-size: 13px;
            resize: none;
            line-height: 1.5;
        }

        #editor:focus {
            outline: none;
        }

        #editor::placeholder {
            color: rgba(255, 255, 255, 0.2);
        }

        ::-webkit-scrollbar {
            width: 8px;
            height: 8px;
        }

        ::-webkit-scrollbar-track {
            background: rgba(0, 0, 0, 0.1);
        }

        ::-webkit-scrollbar-thumb {
            background: rgba(255, 255, 255, 0.2);
            border-radius: 4px;
        }

        ::-webkit-scrollbar-thumb:hover {
            background: rgba(255, 255, 255, 0.3);
        }
    </style>
</head>
<body>
    <div id="desktop">
        <div class="top-bar">Desktop</div>

        <div class="desktop-content">
            <!-- File Manager Window -->
            <div id="files-window" class="window">
                <div class="window-header">
                    <div class="window-title">📁 File Manager</div>
                    <div class="window-controls">
                        <button class="win-close">✕</button>
                    </div>
                </div>
                <div class="window-content">
                    <div id="files-path">/</div>
                    <div class="files-nav">
                        <button class="file-nav-btn" id="files-up">← Up</button>
                    </div>
                    <div class="file-list" id="files-list"></div>
                </div>
            </div>

            <!-- Notepad Window -->
            <div id="notepad-window" class="window">
                <div class="window-header">
                    <div class="window-title">📝 Text Editor</div>
                    <div class="window-controls">
                        <button class="win-close">✕</button>
                    </div>
                </div>
                <div class="notepad-tabs-area">
                    <div id="tabs"></div>
                    <button id="new-tab">+</button>
                </div>
                <div class="window-content">
                    <textarea id="editor" placeholder="Start typing..."></textarea>
                </div>
            </div>
        </div>

        <div id="taskbar">
            <button class="taskbar-btn" id="open-files">📁 Files</button>
            <button class="taskbar-btn" id="open-notepad">📝 Notepad</button>
        </div>
    </div>

    <script>
        // Filesystem structure
        const fileSystem = {
            '/': {
                'bin': { type: 'folder' },
                'etc': { type: 'folder' },
                'home': { type: 'folder' },
                'usr': { type: 'folder' },
                'var': { type: 'folder' }
            },
            '/bin': {},
            '/etc': {},
            '/usr': {},
            '/var': {},
            '/home': {
                'user': { type: 'folder' }
            },
            '/home/user': {
                'Documents': { type: 'folder' },
                'Downloads': { type: 'folder' },
                'Pictures': { type: 'folder' },
                'README.txt': { type: 'file' }
            },
            '/home/user/Documents': {
                'notes.txt': { type: 'file' },
                'project.txt': { type: 'file' }
            },
            '/home/user/Downloads': {
                'file.zip': { type: 'file' }
            },
            '/home/user/Pictures': {
                'photo1.jpg': { type: 'file' },
                'photo2.jpg': { type: 'file' }
            }
        };

        // Window management
        class WindowManager {
            constructor() {
                this.filesWindow = document.getElementById('files-window');
                this.notepadWindow = document.getElementById('notepad-window');
            }

            init() {
                document.getElementById('open-files').addEventListener('click', () => {
                    this.filesWindow.classList.toggle('active');
                });
                document.getElementById('open-notepad').addEventListener('click', () => {
                    this.notepadWindow.classList.toggle('active');
                });

                this.filesWindow.querySelector('.win-close').addEventListener('click', () => {
                    this.filesWindow.classList.remove('active');
                });
                this.notepadWindow.querySelector('.win-close').addEventListener('click', () => {
                    this.notepadWindow.classList.remove('active');
                });

                this.makeDraggable(this.filesWindow);
                this.makeDraggable(this.notepadWindow);

                // Position windows
                this.filesWindow.style.left = '80px';
                this.filesWindow.style.top = '80px';
                this.filesWindow.style.width = '520px';
                this.filesWindow.style.height = '420px';

                this.notepadWindow.style.left = '650px';
                this.notepadWindow.style.top = '80px';
                this.notepadWindow.style.width = '520px';
                this.notepadWindow.style.height = '420px';
            }

            makeDraggable(win) {
                const header = win.querySelector('.window-header');
                let startX, startY, startLeft, startTop;

                header.addEventListener('mousedown', (e) => {
                    if (e.target.classList.contains('win-close')) return;

                    startX = e.clientX;
                    startY = e.clientY;
                    startLeft = win.offsetLeft;
                    startTop = win.offsetTop;

                    const onMove = (e) => {
                        win.style.left = (startLeft + e.clientX - startX) + 'px';
                        win.style.top = (startTop + e.clientY - startY) + 'px';
                    };

                    const onUp = () => {
                        document.removeEventListener('mousemove', onMove);
                        document.removeEventListener('mouseup', onUp);
                    };

                    document.addEventListener('mousemove', onMove);
                    document.addEventListener('mouseup', onUp);
                });
            }
        }

        // File browser
        class FileBrowser {
            constructor() {
                this.currentPath = '/';
                this.pathDisplay = document.getElementById('files-path');
                this.filesList = document.getElementById('files-list');
                this.upBtn = document.getElementById('files-up');
            }

            init() {
                this.upBtn.addEventListener('click', () => this.goUp());
                this.render();
            }

            render() {
                this.pathDisplay.textContent = this.currentPath;
                const contents = fileSystem[this.currentPath] || {};
                this.filesList.innerHTML = '';

                Object.entries(contents).forEach(([name, entry]) => {
                    const div = document.createElement('div');
                    div.className = 'fs-item ' + (entry.type || 'file');

                    const icon = document.createElement('div');
                    icon.className = 'fs-item-icon';
                    icon.textContent = entry.type === 'folder' ? '📁' : '📄';

                    const span = document.createElement('span');
                    span.textContent = name;

                    div.appendChild(icon);
                    div.appendChild(span);

                    if (entry.type === 'folder') {
                        div.addEventListener('dblclick', () => {
                            const newPath = this.currentPath === '/' ?
                                '/' + name :
                                this.currentPath + '/' + name;
                            if (fileSystem[newPath] !== undefined) {
                                this.currentPath = newPath;
                                this.render();
                            }
                        });
                    }

                    this.filesList.appendChild(div);
                });
            }

            goUp() {
                if (this.currentPath === '/') return;
                const parts = this.currentPath.split('/').filter(x => x);
                parts.pop();
                this.currentPath = parts.length ? '/' + parts.join('/') : '/';
                this.render();
            }
        }

        // Notepad with tabs
        class Notepad {
            constructor() {
                this.tabs = [];
                this.activeIdx = 0;
                this.tabsContainer = document.getElementById('tabs');
                this.newTabBtn = document.getElementById('new-tab');
                this.editor = document.getElementById('editor');
                this.storageKey = 'notepad_data';
            }

            init() {
                this.load();
                if (!this.tabs.length) {
                    this.addTab();
                }

                this.newTabBtn.addEventListener('click', () => this.addTab());
                this.editor.addEventListener('input', () => this.save());
                this.render();
            }

            addTab() {
                this.tabs.push({
                    title: `Untitled ${this.tabs.length + 1}`,
                    content: ''
                });
                this.activeIdx = this.tabs.length - 1;
                this.save();
                this.render();
            }

            render() {
                this.tabsContainer.innerHTML = '';
                this.tabs.forEach((tab, i) => {
                    const el = document.createElement('div');
                    el.className = 'tab' + (i === this.activeIdx ? ' active' : '');
                    el.textContent = tab.title;
                    el.addEventListener('click', () => {
                        this.activeIdx = i;
                        this.render();
                    });
                    this.tabsContainer.appendChild(el);
                });

                const tab = this.tabs[this.activeIdx];
                this.editor.value = tab ? tab.content : '';
            }

            save() {
                if (this.tabs[this.activeIdx]) {
                    this.tabs[this.activeIdx].content = this.editor.value;
                    localStorage.setItem(this.storageKey, JSON.stringify({
                        tabs: this.tabs,
                        activeIdx: this.activeIdx
                    }));
                }
            }

            load() {
                const data = localStorage.getItem(this.storageKey);
                if (data) {
                    try {
                        const obj = JSON.parse(data);
                        this.tabs = obj.tabs || [];
                        this.activeIdx = obj.activeIdx || 0;
                    } catch (e) {
                        this.tabs = [];
                        this.activeIdx = 0;
                    }
                }
            }
        }

        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            new WindowManager().init();
            new FileBrowser().init();
            new Notepad().init();
        });
    </script>
</body>
</html>
